  ('alchemy-pay', 'Alchemy Pay', 'monetary-access-rails', 'global-on-ramps', 'https://alchemypay.org', ARRAY[]::text[], ARRAY[]::text[], '{"description": "Alchemy Pay is a global fiat-to-crypto on-ramp that specializes in connecting local payment methods and e-wallets to Ethereum assets, enabling users in emerging and underbanked regions to access crypto via familiar rails.", "extras": {"Access Bottleneck Type": "Local Payment Partners + Regulation + FX Settlement", "Conversion Control Model": "Centralized", "Custody of Funds": "Temporary in-flow custody; settlement via partners to user wallets", "Decentralization Impact": "Expands Ethereum access in emerging markets while introducing reliance on localized, centralized payment partners", "Ethereum Support": "Ethereum Mainnet; Ethereum L2s via supported assets and withdrawals", "Failure Mode": "Specific local rails disabled; country-level access interruption", "Founded Year": "2018", "Freeze / Denial Capability": "Yes", "Geographic Coverage": "Global (Asia-, LATAM-, and emerging-market–strong)", "Headquarters / Primary Jurisdiction": "Singapore (global operations)", "Is Ethereum Required for Core Function?": "Partial (multi-chain support; Ethereum is a primary destination)", "KYC / AML Requirement": "Mandatory; tiered based on payment method and jurisdiction", "Maintaining Organization": "Alchemy Pay", "Number of Countries Supported": "170+ (approx., local-rail dependent)", "On-Ramp vs Exchange Bias": "Access-First", "Practitioner Validation Check": "Is this entity’s primary value proposition enabling users to get fiat value into Ethereum-native assets? Yes", "Practitioner’s Note": "Alchemy Pay is strongest where card and bank penetration is low; practitioners should model local-rail dependency risk and FX settlement complexity alongside regulatory exposure.", "Primary Dependency Risks": "Local payment partners, regulatory shifts, FX settlement", "Primary Function": "Fiat → Crypto Access (Local Rail–Optimized)", "Pri