  ('soci-t-g-n-rale-forge-eurcv-settlement', 'Société Générale – Forge (EURCV Settlement)', 'monetary-access-rails', 'institutional-payment-rails', 'https://forge.societegenerale.com', ARRAY['Ethereum Mainnet (primary)', 'potential L2 usage subject to regulatory approval']::text[], ARRAY[]::text[], '{"description": "Société Générale – Forge provides regulated, euro-denominated institutional settlement infrastructure on Ethereum through EURCV, enabling compliant B2B and capital markets payments with onchain finality while abstracting blockchain complexity from enterprise users.", "extras": {"Abstraction Risk": "Ethereum-Abstracted", "Availability / SLA Expectations": "Enterprise / bank-grade SLAs", "Custody Model": "Qualified custodians; bank-grade custody and account structures", "Ethereum Role in Stack": "Native settlement layer (primary for ERC-20 issuance and transfers)", "Failure Mode": "Issuance or settlement paused due to regulatory or supervisory action", "Founded Year": "2018", "Geographic Scope": "European Union (with cross-border EU reach)", "Headquarters / Primary Jurisdiction": "France / European Union", "Institutional Adoption Level": "Early–Medium (growing institutional pilots)", "Interaction with DeFi": "None to very limited (permissioned, compliance-constrained)", "Interaction with On-Ramps": "Indirect (via institutional banking and treasury channels)", "Interaction with Stablecoins": "Primary settlement medium (issuer of EURCV)", "Is Ethereum Abstracted from End Users?": "Yes (institutional workflows abstract blockchain interaction)", "KYC / AML Enforcement Level": "Institutional-grade", "Maintaining Organization": "Société Générale – Forge (subsidiary of Société Générale)", "Practitioner Validation Check": "Does this entity use Ethereum as a backend settlement layer for institutional-grade payment flows, even if users never touch Ethereum directly? Yes", "Practitioner’s Note": "Forge represents the bank-native, EU-compliant model for Ethereum settlement: strong regulatory legitimacy and balance-sheet trust, but limited composability and slower adoption compared to USD stablecoin rails.", "Primary Dependency Risks": "EU regulatory interpretation, banking supervision, institutional adoption", "Primary Function": "Regulated euro-denominated stablecoin issuance and institutional settlement", "Primary Regulatory Jurisdictions": "European Union (France)", "Primary Use Case": "Euro-denominated B2B settlement, onchain bond settlement, treasury flows", "Programmability Level": "Static to Conditional (policy- and compliance-gated)", "Reason for Inclusion": "Société Générale – Forge qualifies as an Institutional Payment Rail because it uses Ethereum as the backend settlement layer for regulated, high-value euro-denominated institutional payment flows via EURCV.", "Regulatory Posture": "Fully regulated (EU banking and e-money framework)", "Settlement Asset Types": "Stablecoins (EURCV – euro-denominated e-money token)", "Settlement vs Access Classification": "Settlement Rail", "Systemic Importance to Ethereum": "Medium", "Target User Segment": "Financial institutions, enterprises, capital markets participants", "Transaction Scale": "High-value"}, "source_label": "Institutional Payment Rails"}'::jsonb)
) AS v(slug, name, sector_slug, subsector_slug, website, chains, tags, meta)
JOIN public.sectors sec ON sec.slug = v.sector_slug
JOIN public.subsectors s ON s.sector_id = sec.id AND s.slug = v.subsector_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  subsector_id = EXCLUDED.subsector_id,
  website = EXCLUDED.website,
  chains = EXCLUDED.chains,
  tags = EXCLUDED.tags,
  meta = EXCLUDED.meta,
  updated_at = NOW();
